import{towerVisual,towerPoolPlan,massPreservingAllocation}from'../../v02/visual/tower.js';
export const TOWER_SPATIAL_MODE=Object.freeze({ACTUAL_CELL:'ACTUAL_CELL',AGGREGATE_CLUSTER:'AGGREGATE_CLUSTER',ESTIMATED_DISTRIBUTION:'ESTIMATED_DISTRIBUTION'});
export function resolveTowerSpatialMode({providerSpatialKind,geometryEvidence,estimatedDistributionApproved=false}){if(providerSpatialKind==='CELL'||providerSpatialKind==='GRID'){if(geometryEvidence?.actual===true)return TOWER_SPATIAL_MODE.ACTUAL_CELL;throw new Error('ACTUAL_CELL_REQUIRES_PROVIDER_GEOMETRY_EVIDENCE')}if(estimatedDistributionApproved)return TOWER_SPATIAL_MODE.ESTIMATED_DISTRIBUTION;return TOWER_SPATIAL_MODE.AGGREGATE_CLUSTER}
export function buildTowerFrame(records,{deviceClass='desktop',thermalState='NORMAL',estimatedDistributionApproved=false}={}){if(!Array.isArray(records))throw new TypeError('records array required');const values=records.map(r=>Number(r.value)).filter(Number.isFinite);const budget=towerPoolPlan({visibleCount:records.length,deviceClass,thermalState});const items=records.slice(0,budget.renderCount).map(r=>{const spatialMode=resolveTowerSpatialMode({providerSpatialKind:r.providerSpatialKind,geometryEvidence:r.geometryEvidence,estimatedDistributionApproved});const evidenceKind=spatialMode===TOWER_SPATIAL_MODE.ESTIMATED_DISTRIBUTION?'ESTIMATED_DISTRIBUTION':r.evidenceKind??'OFFICIAL_OBSERVATION';return Object.freeze({stableId:String(r.stableId??r.id),spatialMode,geometry:r.geometry??null,visual:towerVisual(Number(r.value),values,{widthM:r.widthM??120,evidenceKind,officialLevel:r.officialLevel??null}),rawValue:Number(r.value),sourceRef:r.sourceRef??null})});return Object.freeze({items,budget,estimatedDistribution:items.some(i=>i.spatialMode===TOWER_SPATIAL_MODE.ESTIMATED_DISTRIBUTION)})}
export function updateStableTowerPool(pool,frame){const next=new Map(pool??[]);const seen=new Set();for(const item of frame.items){seen.add(item.stableId);next.set(item.stableId,item)}for(const id of [...next.keys()])if(!seen.has(id))next.delete(id);return next}
export{towerVisual,towerPoolPlan,massPreservingAllocation};
